"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["88898"],{25053(e){e.exports=JSON.parse('{"id":"FIN-805","slug":"floating-exchange-rate","term":"Floating Exchange Rate","also_known_as":[],"difficulty":"Intermediate","definition":"A floating exchange rate is an exchange rate system in which a currency\'s value is determined by supply and demand in the foreign exchange market, rather than being fixed by the government or central bank.","explanation":["Under a floating system, a currency\'s value changes constantly, rising when demand for it increases and falling when demand weakens. Factors influencing its value include interest rates, inflation, economic growth, trade balances, political stability and investor sentiment.","Most major currencies, including the US dollar, euro, Japanese yen, British pound and Australian dollar, float. Some countries operate a managed float, where the currency mostly floats but the central bank occasionally intervenes to smooth sharp movements.","For example, if a country\'s central bank raises interest rates, foreign investors may buy its currency to earn the higher returns, pushing its value up.","Floating exchange rates allow a country to set its own interest rates to suit its economy and help absorb economic shocks, since the currency can adjust automatically. For example, a weaker currency during a downturn can help exporters. The downside is greater uncertainty, as volatile exchange rates make it harder for businesses to plan and price international trade and investment."],"note":"","total":1500,"prev":{"slug":"flexible-budget","term":"Flexible Budget"},"next":{"slug":"football-field-chart","term":"Football Field Chart"}}')}}]);